SET ROLE hub2_authz_owner;
CREATE OR REPLACE FUNCTION authz.project_resource_catalog(proof text,b jsonb)RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,authz AS $$
DECLARE i jsonb;resolved jsonb;pid uuid;items jsonb;vitems jsonb;citems jsonb;
BEGIN
 IF authz.runtime_role()<>'hub2_hufu'OR b IS NULL OR jsonb_typeof(b)<>'object'OR b-ARRAY['project','project_id']<>'{}'::jsonb THEN RAISE EXCEPTION 'project_resource_catalog_input_invalid';END IF;
 resolved:=authz.authorization_resolve(proof,b);IF resolved->>'state'<>'resolved'THEN RETURN resolved;END IF;pid:=(resolved->'project'->>'project_id')::uuid;i:=authz.vault_current_identity(proof,pid);
 IF NOT authz.client_resource_allowed745((i->>'client_id')::uuid,pid)THEN RAISE EXCEPTION 'software_project_scope_denied' USING ERRCODE='42501';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('resource_kind','typed','target_id',t.id,'type',t.kind,'project_id',s.project_id,'area_id',s.area_id,'region_id',t.region_id,'management_project_id',r.project_id,'use_id',u.id,'revision',u.epoch,'actions',coalesce(u.actions,t.actions),
 'state',CASE WHEN u.id IS NULL THEN'usage_configuration_needed'WHEN NOT u.active THEN'consumer_confirmation_or_revoked'WHEN u.expires_at<=clock_timestamp()THEN'expired'WHEN NOT t.active OR NOT r.active THEN'target_unavailable'ELSE'mapping_active_current_execution_permission_required'END,
 'software_read_ceiling',i->'client_actions'?'resource.read','member_grant_implied',false,
 'management_source_route','/v2/resources/shared/usages/save','consumer_confirmation_route','/v2/resources/shared/usages/confirm','apply_route','/v2/authorization/apply','apply_profile','resource','execute_route','/v2/resources/shared/execute','request_scope',jsonb_build_object('project_id',s.project_id,'area_id',s.area_id,'target_id',t.id,'region_id',t.region_id,'usage_id',u.id))ORDER BY t.id),'[]'::jsonb)INTO items
 FROM authz.shared_resource_bindings s JOIN authz.resource_typed_targets58 t ON t.id=s.target_id JOIN authz.resource_regions58 r ON r.id=t.region_id LEFT JOIN authz.shared_resource_usage u ON u.target_id=s.target_id AND u.project_id=s.project_id AND u.area_id=s.area_id WHERE s.project_id=pid;
 SELECT coalesce(jsonb_agg(jsonb_build_object('resource_kind',CASE WHEN u.entry_id IS NULL THEN'provider'ELSE'vault'END,'use_id',u.id,'entry_id',u.entry_id,'provider_id',u.provider_id,'name',coalesce(e.label,c.provider_id),'mode',u.mode,'project_id',u.project_id,'management_project_id',coalesce(e.project_id,c.project_id),'revision',u.revision,
 'state',CASE WHEN NOT u.active THEN'consumer_confirmation_or_revoked'WHEN u.expires_at<=clock_timestamp()THEN'expired'WHEN e.id IS NOT NULL AND NOT e.active THEN'parent_entry_disabled'WHEN vault2.use_source_valid(u,'source')IS DISTINCT FROM true OR vault2.use_source_valid(u,'consumer')IS DISTINCT FROM true THEN'management_source_invalid'ELSE'active_native_grant_or_execution_scope_required'END,
 'software_action',CASE WHEN u.mode='delivery'THEN'hufu.vault.read'WHEN u.mode IN('asr','model_proxy')THEN'mem.process'ELSE'mem.read'END,
 'software_ceiling_present',i->'client_actions'?CASE WHEN u.mode='delivery'THEN'hufu.vault.read'WHEN u.mode IN('asr','model_proxy')THEN'mem.process'ELSE'mem.read'END,
 'member_grant_implied',false,'apply_route','/v2/vault/project-use/apply','execute_route','/v2/vault/project-use/execute','request_scope',jsonb_build_object('use_id',u.id,'project_id',u.project_id))ORDER BY u.id),'[]'::jsonb)INTO vitems FROM vault2.project_uses u LEFT JOIN vault2.entries e ON e.id=u.entry_id LEFT JOIN authz.provider_capabilities62 c ON c.id=u.provider_id WHERE u.project_id=pid;
 SELECT coalesce(jsonb_agg(jsonb_build_object('resource_kind','registered_project_dependency','provider_id',c.id,'name',c.provider_id,'project_id',c.project_id,'revision',c.revision,'state',coalesce(c.facts->>'registration_state','metadata_registered_execution_binding_required'),'facts',c.facts,'member_grant_implied',false,'secret_included',false,'management_source_route','/v2/providers/capabilities/store','permission_note','Registered dependency facts do not issue member execution permission')ORDER BY c.provider_id),'[]'::jsonb)INTO citems FROM authz.provider_capabilities62 c WHERE c.project_id=pid AND (c.facts->>'secret_values_included')::boolean IS FALSE AND authz.client_resource_allowed745((i->>'client_id')::uuid,pid,c.id,c.provider_id);
 RETURN jsonb_build_object('state','read','project',resolved->'project','items',items||vitems||citems,'production_storage',jsonb_build_object('authority','current_Mem_project_scope','list_route','/v2/resources/storage/list','info_route','/v2/resources/storage/info','restore_route','/v2/resources/storage/restore','status_route','/v2/resources/storage/status','locator','resolved_by_Mem_from_fixed_material_and_version;never_client_bucket_key'),
 'coverage','current_project_registered_bindings_not_private_registry','secrets_included',false,'permission_note','Catalog status is metadata;current actor/software/qualification/source/provider effect checked at execution');
END $$;
REVOKE ALL ON FUNCTION authz.project_resource_catalog(text,jsonb)FROM PUBLIC;
GRANT EXECUTE ON FUNCTION authz.project_resource_catalog(text,jsonb)TO hub2_hufu;
RESET ROLE;
